$\begin{align}
&\phantom{=}\dfrac{dy}{dx}
\\\\
&=\dfrac{d}{dx}(\sqrt{x}\cos(x))
\\\\
&=\dfrac{d}{dx}(\sqrt{x})\cos(x)+\sqrt{x}\dfrac{d}{dx}(\cos(x))&&\gray{\text{The product rule}}
\\\\
&=\dfrac{d}{dx}\left(x^{^{\Large\frac{1}{2}}}\right)\cos(x)+\sqrt{x}\dfrac{d}{dx}(\cos(x))&&\gray{\text{Write }\sqrt{x}\text{ as a power}}
\\\\
&=\dfrac12x^{^{\Large-\frac{1}{2}}}\cdot \cos(x)+\sqrt{x}\cdot (-\sin(x))&&\gray{\text{Differentiate }x^{^{\Large\frac{1}{2}}}\text{ and }\cos(x)}
\\\\
&=\dfrac{\cos(x)}{2\sqrt{x}}-\sqrt{x}\sin(x)&&\gray{\text{Simplify}}
\end{align}$
